-- DIRA LEARN: READ-ONLY check, part 2. Safe on production: it only reads (SELECT).
-- Looks for an object that each migration creates, so it also detects SQL that was pasted into the SQL Editor by hand.
with fn(n) as (select proname from pg_proc where pronamespace = 'public'::regnamespace),
checks(migration, what, present) as (values
  ('01 schema',                      'table organizations',              to_regclass('public.organizations') is not null),
  ('02 rls',                         'function app_role',                exists (select 1 from fn where n = 'app_role')),
  ('03 views and storage',           'function next_participant_no',     exists (select 1 from fn where n = 'next_participant_no')),
  ('04 applications and cohorts',    'function application_transition_allowed', exists (select 1 from fn where n = 'application_transition_allowed')),
  ('05 sessions, curriculum admin',  'table session_reports',            to_regclass('public.session_reports') is not null),
  ('06 assignments and grading',     'function guard_assignment',        exists (select 1 from fn where n = 'guard_assignment')),
  ('07 resources visibility',        'function set_resource_uploader',   exists (select 1 from fn where n = 'set_resource_uploader')),
  ('08 assignment components',       'function guard_assignment_component', exists (select 1 from fn where n = 'guard_assignment_component')),
  ('09 remaining modules',           'function is_trusted_session',      exists (select 1 from fn where n = 'is_trusted_session')),
  ('10 email system',                'table email_templates',            to_regclass('public.email_templates') is not null),
  ('11 courses',                     'table courses',                    to_regclass('public.courses') is not null),
  ('12 learner import',              'table import_batches',             to_regclass('public.import_batches') is not null),
  ('13 first admin setup',           'function first_admin_needed',      exists (select 1 from fn where n = 'first_admin_needed')),
  ('14 applicant approval',          'function can_decide_applications', exists (select 1 from fn where n = 'can_decide_applications')),
  ('15 founder roles',               'role value founder',               exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid where t.typname = 'role_code' and e.enumlabel = 'founder')),
  ('16 curriculum approval centre',  'table curriculum_topic_proposals', to_regclass('public.curriculum_topic_proposals') is not null),
  ('17 executive roles',             'function is_executive',            exists (select 1 from fn where n = 'is_executive')),
  ('18 cohort access windows',       'table learner_access',             to_regclass('public.learner_access') is not null),
  ('19 access rules v2',             'function guard_programme_timezone', exists (select 1 from fn where n = 'guard_programme_timezone')),
  ('20 individual assignments',      'table assignment_recipients',      to_regclass('public.assignment_recipients') is not null),
  ('21 daily briefs',                'table brief_publishers',           to_regclass('public.brief_publishers') is not null),
  ('22 dira connect',                'table connect_conversations',      to_regclass('public.connect_conversations') is not null),
  ('23 v8 audit fixes',              'fixed learner_access_state',       exists (select 1 from pg_proc where proname = 'learner_access_state' and prosrc like '%coalesce(is_trusted_session() or is_staff()%')),
  ('24 safeguarding officers',       'table safeguarding_officers',      to_regclass('public.safeguarding_officers') is not null),
  ('25 connect phase 4 completion',  'table connect_attachments',        to_regclass('public.connect_attachments') is not null),
  ('26 minimum age',                 'function dob_from_form',           exists (select 1 from fn where n = 'dob_from_form')),
  ('27 learner performance',         'table learner_feedback',           to_regclass('public.learner_feedback') is not null),
  ('28 cohort intelligence',         'function ci_intake',               exists (select 1 from fn where n = 'ci_intake')),
  ('29 attachment scanning',         'table connect_attachment_scans',   to_regclass('public.connect_attachment_scans') is not null),
  ('30 curriculum v13',              'table curriculum_lesson_plans',    to_regclass('public.curriculum_lesson_plans') is not null),
  ('31 curriculum v13.1',            'table curriculum_v13_1_sessions',  to_regclass('public.curriculum_v13_1_sessions') is not null),
  ('32 curriculum v13.2',            'table curriculum_v13_2_sessions',  to_regclass('public.curriculum_v13_2_sessions') is not null),
  ('33 security null-role fix',      'table security_fix_33_backup',     to_regclass('public.security_fix_33_backup') is not null),
  ('34 account status enforcement',  'table account_status_events',      to_regclass('public.account_status_events') is not null),
  ('35 file scanning',               'table storage_file_scans',         to_regclass('public.storage_file_scans') is not null),
  ('36 profile bootstrap repair',    'table profile_repair_36_backup',   to_regclass('public.profile_repair_36_backup') is not null),
  ('37 digital marketing topics',    'function apply_digital_marketing_approval_37()', to_regprocedure('public.apply_digital_marketing_approval_37()') is not null),
  ('38 explicit api grants',         'table grants_38_backup; signed-in users can read profiles', to_regclass('public.grants_38_backup') is not null and has_table_privilege('authenticated', 'public.profiles', 'select')),
  ('39 safeguarding interim',        'sg_my_position() knows the interim Super Administrator', position('interim' in pg_get_functiondef('public.sg_my_position()'::regprocedure)) > 0))
select 'objects' as part, migration, what, case when present then 'PRESENT' else 'missing' end as status from checks order by migration;
